"""spec graph: generate "unique code mapping" from code (current-state architecture view).

2026-06-24 spec-markdown-form requirement ①: code itself is the single source of truth. Scan all `.py` files in project
using standard library `ast`, connect edges by import (file = node, import = directed edge, only connect project-internal files,
ignore stdlib/third-party), then overlay **comment convention**—each `.py`'s **file-level docstring** (what this file is responsible for),
each package `__init__.py`'s **module-level docstring** (what this subsystem does overall). Together these three restore the entire architecture.

Intentionally keep it minimal (principle 1 Occam): do not introduce PageRank / tree-sitter / graph libraries / Neo4j
(those are for "squeeze context into prompt budget at runtime", static docs do not need them)."""

from __future__ import annotations

import ast
from pathlib import Path

# Generated artifact filename (CI drift-check target).
ARCHITECTURE_FILENAME = "ARCHITECTURE.md"

_HEADING = "# Current architecture (ARCHITECTURE)"


def iter_py_files(*, package_root: Path) -> list[Path]:
    """All .py files under package_root (sorted, skip __pycache__)."""
    return sorted(path for path in package_root.rglob("*.py") if "__pycache__" not in path.parts)


def module_name(*, path: Path, top_parent: Path) -> str:
    """File path → dot-separated module name (relative to top_parent), __init__ belongs to its containing package."""
    parts = list(path.relative_to(top_parent).with_suffix("").parts)
    if parts and parts[-1] == "__init__":
        parts = parts[:-1]
    return ".".join(parts)


def build_graph(*, package_root: Path) -> tuple[dict[str, Path], list[tuple[str, str]]]:
    """Build graph: return (module_name → file_path mapping, edge list [(src_module, dst_module)]).

    Only connect imports between "project-internal files"; imports pointing to stdlib/third-party/non-existent modules are ignored.
    """
    top_parent = package_root.parent
    nodes: dict[str, Path] = {}
    for path in iter_py_files(package_root=package_root):
        nodes[module_name(path=path, top_parent=top_parent)] = path

    edges: set[tuple[str, str]] = set()
    for src_module, path in nodes.items():
        for target in _imported_modules(path=path, src_module=src_module):
            dst = _resolve_to_node(target=target, nodes=nodes)
            if dst is not None and dst != src_module:
                edges.add((src_module, dst))
    return nodes, sorted(edges)


def missing_docstrings(*, package_root: Path) -> list[str]:
    """Return file paths missing docstring (file-level + package-level __init__). Hard validation of comment convention."""
    missing: list[str] = []
    for path in iter_py_files(package_root=package_root):
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        if not (ast.get_docstring(tree) or "").strip():
            missing.append(str(path))
    return missing


def render_architecture(*, package_root: Path) -> str:
    """Render full ARCHITECTURE.md text (pure function, idempotent): subsystems → components → import relationship graph."""
    nodes, edges = build_graph(package_root=package_root)
    top_parent = package_root.parent

    blocks = [
        _HEADING,
        f"> Generated by `spec graph` from code and docstrings in `{package_root}/`. Do not edit by hand.",
        _render_subsystems(package_root=package_root, top_parent=top_parent),
        _render_relation_graph(nodes=nodes, edges=edges),
    ]
    return "\n\n".join(blocks).rstrip("\n") + "\n"


def write_architecture(*, specs_root: Path, package_root: Path) -> Path:
    """Render + write specs_root/ARCHITECTURE.md to disk, return path."""
    path = specs_root / ARCHITECTURE_FILENAME
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(render_architecture(package_root=package_root), encoding="utf-8")
    return path


def _render_subsystems(*, package_root: Path, top_parent: Path) -> str:
    """Each package (including __init__) = one subsystem section: module-level docstring + file-level docstrings of each file."""
    lines = ["## Subsystems and components"]
    # Package directories (including __init__.py), sorted by path.
    packages = sorted({path.parent for path in iter_py_files(package_root=package_root)})
    for pkg_dir in packages:
        pkg_name = module_name(path=pkg_dir / "__init__.py", top_parent=top_parent) or "(root)"
        init_path = pkg_dir / "__init__.py"
        pkg_doc = _first_line(path=init_path) if init_path.is_file() else ""
        lines.append("")
        lines.append(f"### {pkg_name}")
        lines.append("")
        lines.append(f"_{pkg_doc or '(Module docstring missing)'}_")
        lines.append("")
        lines.append("| Component | Responsibility (first line of the file docstring) |")
        lines.append("|----|----|")
        files = sorted(
            path
            for path in package_root.rglob("*.py")
            if path.parent == pkg_dir and "__pycache__" not in path.parts
        )
        for path in files:
            doc = _first_line(path=path) or "(File docstring missing)"
            lines.append(f"| `{path.name}` | {_cell(doc)} |")
    return "\n".join(lines)


def _render_relation_graph(*, nodes: dict[str, Path], edges: list[tuple[str, str]]) -> str:
    """Import relationship graph (Mermaid): nodes = module short names, edges = imports."""
    lines = ["## Import dependency graph", "", "```mermaid", "graph LR"]
    for module in sorted(nodes):
        lines.append(f'    {_node(module)}["{_short(module)}"]')
    for src, dst in edges:
        lines.append(f"    {_node(src)} --> {_node(dst)}")
    lines.append("```")
    return "\n".join(lines)


def _imported_modules(*, path: Path, src_module: str) -> list[str]:
    """Parse target module names from imports in file (including resolution of relative imports to absolute)."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except SyntaxError:
        return []
    # Relative imports' "." are resolved relative to **the containing package**: for a regular module a.b.c, the package is a.b; for a package __init__, the package is itself.
    is_package = path.name == "__init__.py"
    src_package = src_module if is_package else src_module.rpartition(".")[0]
    targets: list[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            targets.extend(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            base = _absolute_from(module=node.module, level=node.level, src_package=src_package)
            if base is None:
                continue
            # from base import X → candidates are base.X (submodule) and base itself.
            for alias in node.names:
                targets.append(f"{base}.{alias.name}" if base else alias.name)
            if base:
                targets.append(base)
    return targets


def _absolute_from(*, module: str | None, level: int, src_package: str) -> str | None:
    """Resolve `from . / .. import` style relative module names to absolute dot-separated names.

    src_package is the package containing the import (for regular modules, take their parent package; for package __init__, take itself).
    level=1 means src_package itself; level=2 means its parent; and so on.
    """
    if level == 0:
        return module
    parts = src_package.split(".") if src_package else []
    cut = len(parts) - (level - 1)
    base = parts[:cut] if cut >= 0 else []
    if module:
        base = [*base, *module.split(".")]
    return ".".join(base) if base else None


def _resolve_to_node(*, target: str, nodes: dict[str, Path]) -> str | None:
    """Resolve import target to known nodes: exact match, or fall back to its longest known prefix (package)."""
    if target in nodes:
        return target
    parts = target.split(".")
    for cut in range(len(parts) - 1, 0, -1):
        candidate = ".".join(parts[:cut])
        if candidate in nodes:
            return candidate
    return None


def _first_line(*, path: Path) -> str:
    """File's docstring first line (whitespace stripped); empty string if none."""
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except (SyntaxError, OSError):
        return ""
    doc = (ast.get_docstring(tree) or "").strip()
    return doc.split("\n", 1)[0].strip() if doc else ""


def _node(module: str) -> str:
    """Module name → valid Mermaid node name."""
    return "n" + "".join(ch if ch.isalnum() else "_" for ch in module)


def _short(module: str) -> str:
    """Node label: take last two segments, omit lengthy prefix."""
    return ".".join(module.split(".")[-2:])


def _cell(text: str) -> str:
    """Table cell: compress to single line, escape pipes."""
    return text.replace("\n", " ").replace("|", "\\|")
